    public function retryDelay(SmtpOutboundConfigRetryDelayVO|int $retryDelay): static
    {
        $this->retryDelay = $retryDelay;
        $this->retryDelayAssigned = true;
        return $this;
    }
    public function getRetryDelay(): ?int
    {
        return $this->retryDelay instanceof SmtpOutboundConfigRetryDelayVO ? $this->retryDelay->value() : $this->retryDelay;
    }
    public function isRetryDelayAssigned(): bool
    {
        return $this->retryDelayAssigned;
    }
    public function writeRetryDelayTo(mixed $att): void
    {
        if ($this->retryDelayAssigned) {
            \assert(null !== $this->retryDelay);
            $att->retryDelay($this->retryDelay);
        }
    }
    public function readRetryDelayFrom(mixed $att): void
    {
        if ($att->isRetryDelayAssigned()) {
            $retryDelay = $att->getRetryDelay();
            \assert(null !== $retryDelay);
            $this->retryDelay($retryDelay);
        }
    }
    public function unsetRetryDelay(): static
    {
        $this->retryDelayAssigned = false;
        return $this;
    }
    protected function withDefaultRetryDelay(): void
    {
        if ($this->retryDelay === null) {
            $this->retryDelay = 30;
        }
    }
    protected function withAssertedRetryDelayRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->retryDelayAssigned = $this->retryDelayAssigned) {
            $value->retryDelay = SmtpOutboundConfigRetryDelayVO::tryFrom($this->retryDelay, $errorsList);
        }
    }
}
